// ============================================================
// Google Trends Extractor — Bracket-Balanced Parser
// No regex for data extraction; walks chars to find JSON
// ============================================================

const RAW_HTML = $input.first().json.data;

if (typeof RAW_HTML !== 'string') {
  throw new Error('Expected string HTML. Got: ' + typeof RAW_HTML);
}

// -----------------------------------------------------------
// Bracket-balanced extractor
// Walks from a '[' or '{' and finds the matching close char,
// respecting strings and escape sequences. Then tries JSON.parse.
// -----------------------------------------------------------
function extractBalancedJSON(html, start) {
  const open = html[start];
  if (open !== '[' && open !== '{') return null;

  let depth = 0;
  let inStr = false;
  let esc = false;
  let strChar = '';
  const limit = Math.min(start + 6_000_000, html.length);

  for (let i = start; i < limit; i++) {
    const c = html[i];
    if (esc)    { esc = false; continue; }
    if (inStr) {
      if (c === '\\')     { esc = true; continue; }
      if (c === strChar)  { inStr = false; }
      continue;
    }
    if (c === '"' || c === "'") { inStr = true; strChar = c; continue; }
    if (c === '[' || c === '{') { depth++; continue; }
    if (c === ']' || c === '}') {
      depth--;
      if (depth === 0) {
        const raw = html.slice(start, i + 1);
        // Strip Google's %.@. wire-format prefix if present
        const clean = raw.startsWith('%.@.') ? raw.slice(4) : raw;
        try { return JSON.parse(clean); } catch { return null; }
      }
    }
  }
  return null;
}

// -----------------------------------------------------------
// Walk the HTML for every AF_initDataCallback occurrence,
// locate the data: key, skip optional function(){return ...}
// wrapper, then extract with the balanced walker.
// -----------------------------------------------------------
function extractAllCallbacks(html) {
  const results = [];
  const marker = 'AF_initDataCallback';
  let pos = 0;

  while (true) {
    const cbPos = html.indexOf(marker, pos);
    if (cbPos === -1) break;
    pos = cbPos + marker.length;

    const dataKeyPos = html.indexOf('data:', cbPos);
    if (dataKeyPos === -1 || dataKeyPos - cbPos > 600) continue;

    let dataStart = dataKeyPos + 5;
    // Skip whitespace
    while (dataStart < html.length && ' \t\n\r'.includes(html[dataStart])) dataStart++;
    // Skip function(){return ...} wrapper if present
    if (html.slice(dataStart, dataStart + 8) === 'function') {
      const retIdx = html.indexOf('return', dataStart);
      if (retIdx !== -1 && retIdx - dataStart < 60) {
        dataStart = retIdx + 6;
        while (dataStart < html.length && ' \t\n\r'.includes(html[dataStart])) dataStart++;
      }
    }

    const payload = extractBalancedJSON(html, dataStart);
    if (payload !== null) results.push(payload);
  }

  return results;
}

// -----------------------------------------------------------
// Recursively search parsed payloads for the trends rows.
// Signature: an array of arrays where each row has
//   - at least 6 elements
//   - row[0] is a non-empty string (the query)
// Checks first 3 rows to confirm the pattern.
// -----------------------------------------------------------
function findTrendsArray(node, depth = 0) {
  if (depth > 10 || !node || typeof node !== 'object') return null;

  if (Array.isArray(node) && node.length >= 3) {
    const looksLikeTrends = node
      .slice(0, Math.min(3, node.length))
      .every(row => Array.isArray(row) && row.length >= 6 && typeof row[0] === 'string' && row[0].length > 0);
    if (looksLikeTrends) return node;
  }

  const children = Array.isArray(node) ? node : Object.values(node);
  for (const child of children) {
    if (child && typeof child === 'object') {
      const found = findTrendsArray(child, depth + 1);
      if (found) return found;
    }
  }
  return null;
}

// -----------------------------------------------------------
// Run extraction
// -----------------------------------------------------------
const payloads = extractAllCallbacks(RAW_HTML);

if (payloads.length === 0) {
  const cbCount = (RAW_HTML.match(/AF_initDataCallback/g) || []).length;
  throw new Error(
    `No parseable AF_initDataCallback payloads found. ` +
    `Saw ${cbCount} callback marker(s) in ${RAW_HTML.length} chars. ` +
    `HTML snippet (first 500 chars): ${RAW_HTML.slice(0, 500)}`
  );
}

let trendsRows = null;
for (const payload of payloads) {
  trendsRows = findTrendsArray(payload);
  if (trendsRows) break;
}

if (!trendsRows) {
  throw new Error(
    `Parsed ${payloads.length} callback payload(s) but no trends rows found inside. ` +
    `Top-level types: ${payloads.map(p => Array.isArray(p) ? 'array['+p.length+']' : 'object').join(', ')}`
  );
}

// -----------------------------------------------------------
// Map raw rows → clean named objects
//
// Row index reference:
//   [0]  query string
//   [1]  entity/topic name (or null)
//   [2]  country code
//   [3]  [startTimestamp]  — unix seconds in a 1-item array
//   [4]  [endTimestamp]    — unix seconds in a 1-item array
//   [6]  search volume estimate
//   [8]  trend/breakout score
//   [9]  related queries   — string[]
//   [10] category IDs      — number[]
//   [12] normalized query
// -----------------------------------------------------------
function toISO(ts)          { return ts ? new Date(ts * 1000).toISOString() : null; }
function safe(arr, i, fb)   { return Array.isArray(arr) && arr[i] != null ? arr[i] : (fb ?? null); }
function tsFromWrapped(arr) { return Array.isArray(arr) && arr[0] != null ? arr[0] : null; }

return trendsRows.map(row => ({
  json: {
    query:           safe(row, 0, ''),
    entity:          safe(row, 1),
    country:         safe(row, 2, 'US'),
    startTime:       toISO(tsFromWrapped(row[3])),
    endTime:         toISO(tsFromWrapped(row[4])),
    searchVolume:    safe(row, 6, 0),
    trendScore:      safe(row, 8, 0),
    relatedQueries:  Array.isArray(row[9])  ? row[9]  : [],
    categoryIds:     Array.isArray(row[10]) ? row[10] : [],
    normalizedQuery: safe(row, 12) || safe(row, 0, ''),
  }
}));

// 1. Grab ALL trend items that passed the 'If' node (not just the first)
const allTrends = $('If Trend Active').all().map(i => i.json);

// 2. Grab the array of matches from the AI Agent's structured output
const matchesArray = $input.first().json.output?.matches || [];

const successfulMatches = [];

for (const item of matchesArray) {
  const termString = String(item.term).toLowerCase();

  // 3. Find which original trend this AI match actually corresponds to
  const matchedTrend = allTrends.find(trend => {
    const queryString = String(trend.query).toLowerCase();
    return termString.includes(queryString) || queryString.includes(termString);
  });

  if (matchedTrend) {
    successfulMatches.push({
      term: item.term,
      reason: item.reason,
      original_query: matchedTrend.query,
      original_data: matchedTrend
    });
  }
}

// 4. If nothing matched, still return a clean, single-item shape
if (successfulMatches.length === 0) {
  return [{
    json: {
      matches: [],
      message: "No physical retail or logistics trends stood out this week — nothing worth flagging."
    }
  }];
}

// 5. Helper to make big numbers readable (e.g. 100000 -> 100K)
function formatVolume(n) {
  if (n >= 1000000) return (n / 1000000).toFixed(n % 1000000 === 0 ? 0 : 1) + 'M';
  if (n >= 1000) return (n / 1000).toFixed(n % 1000 === 0 ? 0 : 1) + 'K';
  return String(n);
}

// 6. Build a conversational, Slack mrkdwn-formatted message
const lines = successfulMatches.map(m => {
  const vol = formatVolume(m.original_data.searchVolume);
  return `• *${m.original_query}* — ~${vol} searches this week (trend score: ${m.original_data.trendScore}). ${m.reason}`;
});

const intro = successfulMatches.length === 1
  ? `Found a trend this week worth a look 👀`
  : `Found ${successfulMatches.length} trends this week worth a look 👀`;

const message = `${intro}\n\n${lines.join('\n')}`;

// 7. Return ONE item with both the raw matches and the message
return [{
  json: {
    matches: successfulMatches,
    message
  }
}];
